$ErrorActionPreference = "Stop"

Write-Host "=== PATCH ROLE FINAL - SINKRON CRUD ===" -ForegroundColor Cyan
Write-Host "Patch ini mengganti file role berdasarkan source terbaru yang diperiksa." -ForegroundColor Gray
Write-Host ""

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupDir = ".\backup-role-final-$timestamp"
New-Item -ItemType Directory -Path $backupDir -Force | Out-Null

$files = @(
    "src\database.ts",
    "src\employee.ts",
    "src\index.ts",
    "src\attendance.ts",
    "src\report.ts",
    "src\xlsx.ts",
    "public\pegawai.html",
    "public\pegawai.js",
    "public\tambah-rekap.js",
    "public\edit-rekap.js",
    "public\rekap-bulanan.js",
    "public\rekap-bulanan.html",
    "data\absensi.sqlite"
)

foreach ($file in $files) {
    if (Test-Path $file) {
        $dest = Join-Path $backupDir $file
        $destDir = Split-Path $dest -Parent
        if (-not (Test-Path $destDir)) { New-Item -ItemType Directory -Path $destDir -Force | Out-Null }
        Copy-Item $file $dest -Force
    }
}

Write-Host "Backup: $backupDir" -ForegroundColor Yellow

function Write-Base64File {
    param([string]$Path, [string]$Data)
    $dir = Split-Path $Path -Parent
    if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    $bytes = [Convert]::FromBase64String(($Data -replace "\s", ""))
    [System.IO.File]::WriteAllBytes((Join-Path (Get-Location) $Path), $bytes)
    Write-Host "OK $Path" -ForegroundColor Green
}

